    public static string Updater(string state,bool linux)
    {
        if(state.Contains("Cryptographic",StringComparison.OrdinalIgnoreCase)||state.Contains("подпис",StringComparison.OrdinalIgnoreCase)&&state.Contains("ошиб",StringComparison.OrdinalIgnoreCase))return global::SysAdminAssistant.Core.ProductText.Get("Проверка подписи не пройдена. Проверьте целостность пакета сервера, издателя и актуальность доверия агента. Не отключайте проверку подписи и не подменяй доверенный ключ ради установки.");
        if(state.Contains("HttpRequest",StringComparison.OrdinalIgnoreCase))return global::SysAdminAssistant.Core.ProductText.Get("Проверьте HTTPS-связь с сервером, время, доверие сертификату и наличие пакета агента в серверной публикации. Убедитесь, что агент подтверждён и не отозван. Ошибка загрузки обновления сама по себе не означает потерю мониторинга.");
        if(state.Contains("IOException",StringComparison.OrdinalIgnoreCase)||state.Contains("UnauthorizedAccess",StringComparison.OrdinalIgnoreCase))return global::SysAdminAssistant.Core.ProductText.Get("Проверьте свободное место и права в каталоге данных/программы агента, блокировку файлов и журнал установщика. Не выдавай права записи всем пользователям.");
        if(state.Contains("не заверш",StringComparison.OrdinalIgnoreCase)||state.Contains("ошиб",StringComparison.OrdinalIgnoreCase)||state.Contains("откат",StringComparison.OrdinalIgnoreCase))return global::SysAdminAssistant.Core.ProductText.Get("Проверьте журнал обновления и статус службы, целостность пакета сервера и предыдущую рабочую версию. ")+(linux?global::SysAdminAssistant.Core.ProductText.Get("Проверьте systemctl status sysadminassistant-agent-update.timer и journalctl -u sysadminassistant-agent-update.service -n 100 --no-pager."):global::SysAdminAssistant.Core.ProductText.Get("Проверьте журнал службы обновления агента и Windows Application/System."))+global::SysAdminAssistant.Core.ProductText.Get(" Не удаляйте ключ агента и данные регистрации для обхода ошибки.");
        return global::SysAdminAssistant.Core.ProductText.Get("Это обновление самого агента, а не ОС. ")+(linux?global::SysAdminAssistant.Core.ProductText.Get("Загрузка проверяется подписью; применение выполняет отдельный systemd-таймер. Если ожидание затянулось, проверьте состояние таймера и его журнал."):global::SysAdminAssistant.Core.ProductText.Get("Если ожидание затянулось, проверьте службу обновления и её журнал."))+global::SysAdminAssistant.Core.ProductText.Get(" Не устанавливайте непроверенный пакет.");
    }
