            "reboot" or "power" or "shutdown" or "bsod"=>global::SysAdminAssistant.Core.ProductText.Get("Сопоставь System 41/6008, 1074 и 1001, журнал гипервизора/ИБП и установку обновлений. Проверьте дамп при bugcheck. Факт перезагрузки не устанавливает причину; 41 не доказывает отказ блока питания."),
            "planned"=>global::SysAdminAssistant.Core.ProductText.Get("Сверьте инициатора и причину перезагрузки с работами/обновлениями; проверьте, что службы и приложения после загрузки работают."),
            "ntfs" or "ntfs2" or "disk" or "stor" or "linux-storage"=>global::SysAdminAssistant.Core.ProductText.Get("Сначала проверьте резервную копию и состояние диска/RAID/гипервизора, свободное место и соседние ошибки ввода-вывода. Затем планируй диагностику ФС. Не форматируйте диск и не запускайте исправление ФС вслепую на рабочем узле."),
