            "app" or "dotnet"=>global::SysAdminAssistant.Core.ProductText.Get("Откройте Application и журнал программы в момент сбоя; сохраните модуль, код исключения и стек. Проверьте версию, зависимости и недавние изменения; перезапуск может временно скрыть причину."),
            "fail-login" or "linux-login"=>global::SysAdminAssistant.Core.ProductText.Get("Сверьте IP, учётную запись и частоту попыток. Проверьте, не использует ли служба/задание старый пароль. При внешних неизвестных попытках проверьте ограничения доступа и журналы успешных входов; одни неудачные попытки не доказывают взлом."),
            "logon-success"=>global::SysAdminAssistant.Core.ProductText.Get("Проверьте, кто и откуда успешно вошёл, тип входа и связь с предыдущими неудачами. Сверьте с администратором; при неподтверждённом входе сохраните журналы и действуй по процедуре реагирования."),
            "lock"=>global::SysAdminAssistant.Core.ProductText.Get("Найдите источник неверных паролей, проверьте службы, задания и сохранённые подключения. Разблокировка без устранения источника может привести к повторной блокировке."),
            "audit-clear" or "audit-policy" or "group"=>global::SysAdminAssistant.Core.ProductText.Get("Сверьте инициатора, время и изменённые объекты с согласованными работами. Сохраните доступные журналы; неожиданная очистка/смена аудита или прав требует расследования, но сама по себе не устанавливает виновника."),
            "threat"=>global::SysAdminAssistant.Core.ProductText.Get("Откройте сведения Defender: объект, действие и результат устранения. Проверьте, завершено ли удаление/карантин, и проведи проверку по процедуре организации. Не восстанавливай обнаруженный файл и не отключайте защиту ради снятия тревоги."),
            "defender-off" or "defender-on"=>global::SysAdminAssistant.Core.ProductText.Get("Проверьте реальное состояние защиты и политики, наличие другого антивируса и согласованные работы. Не отключайте защиту для обхода сообщения; сопоставь с последующим событием восстановления."),
            "updates-failed"=>global::SysAdminAssistant.Core.ProductText.Get("Откройте журнал установки обновления и код ошибки, проверьте свободное место, ожидаемую перезагрузку и журнал Windows Update/CBS. Исправление выбирай по точному коду, а не сбрасывай компоненты обновления наугад."),
            "sql-io" or "sql-retry"=>global::SysAdminAssistant.Core.ProductText.Get("Проверьте SQL ERRORLOG, номер базы/страницы и состояние хранилища, сохраните резервные копии. Проверку целостности согласуйте с DBA; не применяй режимы восстановления с потерей данных по одному уведомлению."),
            "ad"=>global::SysAdminAssistant.Core.ProductText.Get("Проверьте DNS, время, доступность партнёров репликации и результаты repadmin /replsummary. Сопоставь событие с конкретным контроллером/разделом; не выполняй принудительное удаление объектов или восстановление AD без диагностики."),
            "dns"=>global::SysAdminAssistant.Core.ProductText.Get("Проверьте состояние DNS, загрузку зон, доступность AD и upstream, а также точный текст события. Для DNS на контроллере сопоставь с завершением загрузки AD; не меняйте зоны вслепую."),
            _=>global::SysAdminAssistant.Core.ProductText.Get("Сопоставь источник, ID и полный текст события с назначением узла и недавними изменениями. Для пользовательского правила точная причина не определена: проверьте совпадение условий и журнал приложения; не выполняй изменения автоматически.")};
        var facts=global::SysAdminAssistant.Core.ProductText.Get($"Последнее обнаружение: {last.ToServerTime():dd.MM.yyyy HH:mm:ss}; учтено событий: {count}.")+(source==""?"":global::SysAdminAssistant.Core.ProductText.Get(" Группа/источник: ")+source+".");
        if(rule!=null)facts+=global::SysAdminAssistant.Core.ProductText.Get($" Правило: {rule.Name}; журнал {rule.Channel}, источник {rule.Provider}, ID {string.Join(",",rule.Ids)}; порог {rule.Threshold} за {rule.WindowMinutes} мин.");
        var recent=evidence.OrderByDescending(e=>e.TimeUtc).FirstOrDefault();
        var close=id=="linux-reboot"?global::SysAdminAssistant.Core.ProductText.Get("Это уведомление о новом запуске; текущее состояние определяется свежими отчётами агента."):quiet>0?global::SysAdminAssistant.Core.ProductText.Get($"Автозакрытие после {quiet} мин. без новых событий при доступном журнале; новая попытка начинает ожидание заново."):id=="linux-service"?global::SysAdminAssistant.Core.ProductText.Get("Закрывается после свежего подтверждения Running этой службы либо вручную после разбора."):id=="reboot"?global::SysAdminAssistant.Core.ProductText.Get("Закрывается после подтверждённого периода стабильной работы либо вручную после разбора."):global::SysAdminAssistant.Core.ProductText.Get("Ручное подтверждение после разбора; одна только кнопка «Решено» не исправляет причину.");
        return facts+global::SysAdminAssistant.Core.ProductText.Get("\nЧто проверить и как устранить: ")+steps+global::SysAdminAssistant.Core.ProductText.Get("\nЗакрытие: ")+close+(!includeEvidence?"":recent==null?global::SysAdminAssistant.Core.ProductText.Get("\nИсходная запись уже не сохранена; причина требует проверки на узле."):global::SysAdminAssistant.Core.ProductText.Get($"\nПоследняя запись: {recent.TimeUtc.ToServerTime():dd.MM.yyyy HH:mm:ss} · {recent.Provider} / {recent.Id}\n")+recent.Message);
    }
}
